@track_db_query("healthcheck")
def check_database_health():
    conn = get_db_connection()
    cursor = conn.cursor()
    try:
        cursor.execute("SELECT 1")
        return cursor.fetchone()
    finally:
        cursor.close()
        conn.close()


@track_db_query("select_url_for_redirect")
def fetch_url_for_redirect(short_code):
    conn = get_db_connection()
    cursor = conn.cursor()
    try:
        cursor.execute(
            """
            SELECT url, status, expiration_time
            FROM urls
            WHERE short_url = %s
            """,
            (short_code,),
        )
        return cursor.fetchone()
    finally:
        cursor.close()
        conn.close()


