@track_db_query("select_basic_analytics")
def fetch_basic_analytics(short_code):
    conn = get_db_connection()
    cursor = conn.cursor()
    try:
        cursor.execute(
            """
            SELECT short_url, url, status
            FROM urls
            WHERE short_url = %s
            """,
            (short_code,),
        )
        url_data = cursor.fetchone()

        if not url_data:
            return None, 0, []

        cursor.execute(
            "SELECT COUNT(*) FROM click_events WHERE short_url = %s",
            (short_code,),
        )
        total_result = cursor.fetchone()
        total_clicks = int(total_result[0]) if total_result and total_result[0] is not None else 0

        cursor.execute(
            """
            SELECT ip_address, clicked_at
            FROM click_events
            WHERE short_url = %s
            ORDER BY clicked_at DESC
            LIMIT 10
            """,
            (short_code,),
        )
        recent_clicks = cursor.fetchall()

        return url_data, total_clicks, recent_clicks
    finally:
        cursor.close()
        conn.close()


def get_client_ip():
    forwarded_for = request.headers.get("X-Forwarded-For")
    if forwarded_for:
        return forwarded_for.split(",")[0].strip()

    return (
        request.headers.get("X-Real-IP")
        or request.remote_addr
        or "Unknown"
    )


