@app.route("/health", methods=["GET"])
@track_request_metrics
def health_check():
    health_status = {
        "status": "healthy",
        "service": "redirect-service",
        "timestamp": datetime.now().isoformat(),
        "checks": {},
    }

    overall_healthy = True

    try:
        check_database_health()
        health_status["checks"]["database"] = "connected"
    except Exception as exc:
        health_status["checks"]["database"] = f"failed: {str(exc)}"
        overall_healthy = False

    try:
        redis_client.ping()
        health_status["checks"]["redis"] = "connected"
    except Exception as exc:
        health_status["checks"]["redis"] = f"failed: {str(exc)}"
        overall_healthy = False

    try:
        channel = getattr(click_tracker, "channel", None)
        if channel is None or getattr(channel, "is_closed", False):
            raise RuntimeError("RabbitMQ channel unavailable")
        health_status["checks"]["rabbitmq"] = "connected"
    except Exception as exc:
        health_status["checks"]["rabbitmq"] = f"degraded: {str(exc)}"

    if not overall_healthy:
        health_status["status"] = "unhealthy"
        return json_response(health_status, 503)

    return json_response(health_status, 200)


@app.route("/<short_code>", methods=["GET"])
@track_request_metrics
def redirect_to_url(short_code):
    original_url = get_cached_url(short_code)

    if original_url:
        CACHE_HIT_COUNT.labels(status="hit").inc()
    else:
        CACHE_HIT_COUNT.labels(status="miss").inc()

        try:
            result = fetch_url_for_redirect(short_code)
        except Exception as exc:
            REDIRECT_ERRORS.labels(error_type="db_error").inc()
            return json_response(
                {
                    "error": "Database error",
                    "details": str(exc),
                },
                500,
            )

        if not result:
            REDIRECT_ERRORS.labels(error_type="not_found").inc()
            return json_response(
                {
                    "error": "URL not found",
                    "short_code": short_code,
                },
                404,
            )

        original_url, status, expiration_time = result

        if status != "active":
            REDIRECT_ERRORS.labels(error_type="inactive").inc()
            return json_response(
                {
                    "error": "URL is disabled",
                    "short_code": short_code,
                    "status": status,
                },
                410,
            )

        if expiration_time and datetime.now() > expiration_time:
            REDIRECT_ERRORS.labels(error_type="expired").inc()
            return json_response(
                {
                    "error": "URL has expired",
                    "short_code": short_code,
                    "expired_at": expiration_time.isoformat(),
                },
                410,
            )

        set_cached_url(short_code, original_url)

    try:
        click_data = {
            "short_url": short_code,
            "clicked_at": datetime.now().isoformat(),
            "user_agent": request.headers.get("User-Agent", "Unknown"),
            "ip_address": get_client_ip(),
            "referrer": request.headers.get("Referer"),
        }
        click_tracker.track_click(click_data)
    except Exception as exc:
        logger.warning("Failed to track click for %s: %s", short_code, exc)

    REDIRECTS_TOTAL.labels(short_code=short_code).inc()
    return redirect(original_url, code=301)


@app.route("/stats/<short_code>", methods=["GET"])
@track_request_metrics
def get_stats(short_code):
    try:
        result = fetch_url_stats(short_code)

        if not result:
            return json_response({"error": "URL not found"}, 404)

        url, clicks, created_at, last_accessed, status, created_by = result

        return json_response(
            {
                "short_url": f"{Config.BASE_URL}{short_code}",
                "original_url": url,
                "clicks": clicks,
                "created_at": created_at.isoformat() if created_at else None,
                "last_accessed": last_accessed.isoformat() if last_accessed else None,
                "status": status,
                "created_by": created_by,
            },
            200,
        )
    except Exception as exc:
        return json_response(
            {
                "error": "Failed to retrieve statistics",
                "details": str(exc),
            },
            500,
        )


