@app.route("/analytics/top-urls", methods=["GET"])
@track_request_metrics
def get_top_urls():
    try:
        limit = int(request.args.get("limit", 10))
        days = request.args.get("days")
        days = int(days) if days else None

        if limit < 1 or limit > 100:
            return json_response({"error": "Limit must be between 1 and 100"}, 400)

        if days and (days < 1 or days > 365):
            return json_response({"error": "Days must be between 1 and 365"}, 400)

        top_urls = analytics_service.get_top_urls(limit, days)

        return json_response(
            {
                "limit": limit,
                "days": days,
                "count": len(top_urls),
                "urls": top_urls,
            },
            200,
        )
    except Exception as exc:
        return json_response(
            {
                "error": "Failed to retrieve top URLs",
                "details": str(exc),
            },
            500,
        )


@app.route("/analytics/<short_code>", methods=["GET"])
@track_request_metrics
def get_analytics(short_code):
    try:
        url_data, total_clicks, recent_clicks = fetch_basic_analytics(short_code)

        if not url_data:
            return json_response({"error": "Short URL not found"}, 404)

        response = json_response(
            {
                "short_url": short_code,
                "original_url": url_data[1],
                "status": url_data[2],
                "total_clicks": total_clicks,
                "recent_clicks": [
                    {
                        "ip": click[0] if click[0] else "Unknown",
                        "timestamp": click[1].isoformat() if click[1] else None,
                    }
                    for click in recent_clicks
                ],
            },
            200,
        )
        response.headers.add("Access-Control-Allow-Origin", "*")
        return response
    except Exception as exc:
        logger.exception("Error fetching analytics for %s", short_code)
        return json_response(
            {
                "error": "Failed to fetch analytics",
                "details": str(exc),
            },
            500,
        )


